        emon.Port.Cells st = emon.Port.newCells();
        emon.Port.Cells pal = emon.Port.newCells();
        emon.Port.Cells info = emon.Port.newCells();
        emon.Port.Buf idat = emon.Port.newBuf();
        int v = 0;
        int i = 0;
        while (i < 16) {
            emon.Port.cellsPush(info, 0);
            i += 1;
        }
        Pngprobe.ppBuild(2, ws, out, z, raw, row, st, pal);
        emon.Testport.assertEq(ptRead(emon.Port.bufBlob(out), info, idat), 0, "well formed before");
        v = emon.Port.bufAt(out, 20);
        emon.Port.bufSet(out, 20, v ^ 1);
        emon.Testport.assertEq(ptRead(emon.Port.bufBlob(out), info, idat), 2, "IHDR CRC fails");
        emon.Port.bufSet(out, 20, v);
